update public.divisions set description = 'Researching the foundations of machine intelligence — from large-scale reasoning systems and emergent capabilities to rigorous evaluation science. We build open models, benchmarks, and training infrastructure that advance the frontier of artificial intelligence while remaining fully reproducible.', focus_areas = array['Reasoning systems','Scaling laws','Evaluation science'] where slug='ai';
update public.divisions set description = 'Advancing quantum information science across computing architectures, sensing platforms, and post-quantum cryptographic protocols. Our work spans superconducting qubit systems, photonic networks, and error-correcting codes designed for fault-tolerant operation at scale.', focus_areas = array['Superconducting qubits','Quantum sensing','Post-quantum crypto'] where slug='quantum';
update public.divisions set description = 'Bridging computational science and clinical medicine to develop diagnostic tools, genomic analysis pipelines, and therapeutic discovery platforms. We partner with hospitals and research institutions to translate open science into measurable patient outcomes.', focus_areas = array['Genomic analysis','Medical imaging','Therapeutic discovery'] where slug='medical';
update public.divisions set description = 'Developing bidirectional brain-computer interfaces, neural decoding algorithms, and high-resolution cortical mapping techniques. Our research aims to restore communication and motor function for patients with neurological conditions while advancing fundamental neuroscience.', focus_areas = array['Neural decoding','Cortical mapping','Motor prosthetics'] where slug='neuro';
update public.divisions set description = 'Building autonomous systems that perceive, reason, and act in unstructured environments. From dexterous manipulation and legged locomotion to multi-agent coordination, we develop the control algorithms and hardware platforms that enable robots to work alongside humans.', focus_areas = array['Dexterous manipulation','Legged locomotion','Multi-agent systems'] where slug='robotics';
update public.divisions set description = 'Designing next-generation computing hardware — from neuromorphic silicon and photonic accelerators to domain-specific architectures optimized for AI workloads. We tape out open chips, publish full RTL, and build the tooling that makes custom silicon accessible to researchers.', focus_areas = array['Neuromorphic silicon','Photonic computing','Open RTL'] where slug='chip';